  petersburg: ['冬宫（艾尔米塔什），孔雀石厅整面墙是绿色石头拼的', '彼得霍夫宫，大瀑布阶下镀金雕像一路排到海边（喷泉 4 月下旬—10 月中旬开，关水后下园无水景）', '圣以撒大教堂，柱廊顶上绕一圈，全城的屋顶都在下面', '涅瓦大街，戈斯季内德沃尔百货那一段的连续拱廊', '彼得保罗要塞，中午十二点城墙上放一炮', '夏园，铸铁栅栏后面一排白色大理石雕像（周二闭园，4 月整月维护）', '涅瓦河游船，从喷泉河拐进大涅瓦，过桥洞时头顶只剩一线天'],
