  murmansk: ['阿廖沙纪念碑，山崖上那尊灰绿色混凝土士兵，脚下是整个港口', '列宁号破冰船，1957 年的核动力船体，能下到反应堆舱外面', '捷里别尔卡，巴伦支海边最后一排木屋，沙滩上搁着船的骨架', '五角广场，列宁大街上鱼摊、花店和公交车挤在一处', '摩尔曼斯克地方志博物馆，北方航线那间展厅放着破冰船模型', '谢苗诺夫湖，湖边长椅，极夜那几个月路灯一直亮着', '跟船出海看鲸，夏天从捷里别尔卡码头出去，坐三四个小时'],
