/**
 * 有常设演出的地方：剧院、音乐厅、有固定驻场乐队的场子（2026-11-07 加）。
 *
 * ## 为什么单独一格，不塞进 `night`
 *
 * `night` 是「只有夜里才成立的那个去处」，一座城只能有一条：要么逛夜市，要么听戏。
 * 而这两件事常常同时存在 —— 苏州有夜花园也有昆剧院。挤在一个字段里，
 * 只能二选一，等于每次都替她扔掉一个。
 *
 * ## 排在哪一天
 *
 * 第二天晚上。理由：第一天刚到，晚上该去看这座城本来的样子（夜市、开桥、亮灯）；
 * 第二天她已经熟悉了，去看一场戏才不显得突兀。而且**只排一次** ——
 * 「每晚都有戏」不真实，也会把那座城真正的夜色盖掉。
 *
 * 空数组 = 这城没有能站得住的常设演出，那天晚上照旧回酒店。
 */
