const C = (
  id: string, name: string, region: string, lat: number, lon: number,
  tags: readonly string[], hubs: { air?: boolean; rail?: boolean; port?: boolean } = {},
): City => ({
  id, name, region, country: 'CN', lat, lon, tz: 'Asia/Shanghai',
  air: hubs.air ?? true, rail: hubs.rail ?? true, port: hubs.port ?? false, tags,
  spots: SPOTS[id] ?? [],
  foods: FOODS[id] ?? [],
  slots: expandSlots(SPOTS[id] ?? []),
  shows: SHOWS[id] ?? [],
  night: NIGHTS[id] ?? null,
  festivals: FESTIVALS[id] ?? [],
  lore: LORE[id] ?? null,
  priceIdx: priceIdxOf(id),
});

const F = (
  id: string, name: string, country: City['country'], lat: number, lon: number, tz: string,
  tags: readonly string[],
  /**
   * 2026-11-01 加：国外城市也有「没机场 / 没客运铁路」的。
   * 原来这里写死三个 true，于是**京都能选飞机、里约能选火车** ——
   * 京都最近的机场在大阪关西，巴西全国没有长途客运铁路。
   */
  hubs: { air?: boolean; rail?: boolean; port?: boolean } = {},
): City => ({
  id, name, region: country, country, lat, lon, tz,
  air: hubs.air ?? true, rail: hubs.rail ?? true, port: hubs.port ?? true, tags,
  spots: SPOTS[id] ?? [],
  foods: FOODS[id] ?? [],
  slots: expandSlots(SPOTS[id] ?? []),
  shows: SHOWS[id] ?? [],
  night: NIGHTS[id] ?? null,
  festivals: FESTIVALS[id] ?? [],
  lore: LORE[id] ?? null,
  priceIdx: priceIdxOf(id),
});


/**
 * 视觉锚点 —— **这座城市看去是什么样**。一句话，写颜色、材质、形状、光线。
 *
 * ## 为什么非有它不可
 *
 * 提示词原来只有地名（「九寨沟的甘海子」）。文生图模型不认识「甘海子」，
 * 只能自由发挥 —— 2026-11-04 实测，同一句、同一颗种子：
 *
 * - 只有地名：一张普通的暖金色高原湖，跟九寨沟没关系
 * - 加上「钙化池层层叠落，水呈孔雀蓝到翡翠绿，池底沉木可见，两岸针阔混交林」：
 *   一眼就认得出是九寨沟
 *
 * ## 写这条的规矩
 *
 * 1. **只写有把握真实存在的东西。** 这跟 `spots` 是同一条底线：
 *    拿不准具体细节，就退到地形和气候（「红土丘陵连绵，桉树林灰绿色」），
 *    绝不编。编错了没人能发现，但每张照片都会以假乱真地错下去。
 * 2. **只写看得见的**：不写吃什么、什么历史、什么活动 —— 那些不落在画面上。
 * 3. **20–45 字**。再长会盖过场景描述，再短等于没说。
 * 4. 不写评价词（「很美」「令人惊叹」）—— 模型会把它们当风格指令，出来一片糖水。
 * 5. **主景旁边还有什么，必须写。** 这一条踩过三次：
 *    - 拉萨：「布达拉宫白墙暗红宫室层叠」→ 被画成荒山里的孤宫（没写它在城里）
 *    - 曼谷：「郑王庙灰白塔身…」→ 被画成荒野孤庙（没写河对岸是城区）
 *    - 敦煌：「月牙泉一弯深绿水」→ 泉边被编出一片密集村寨
 *      （实际那儿是**月泉阁**：一座四层六角木楼阁，飞檐青瓦，1991 年按汉唐风格复建）
 *
 *    规律很清楚：**你只写主角，模型就会替你把配角编出来**，而且编得毫不含糊。
 *    所以写地标时要带上「它周围是什么」—— 是城区、是对岸楼群、还是只有一座楼。
 *
 * 这一版是 2026-11-04 按 127 个城市逐条写的，国内 90、国外 37；当天又逐条上网核过一遍，
 * 改掉 11 条事实错误（见 CHANGELOG 0.5.37），随后又逐张出图检查、修了上面那三处「缺配角」。
 */
