  suzdal: '小河在草甸里绕弯，对岸白墙教堂顶着绿洋葱顶，木屋栅栏沿路排开',
  nizhnynovgorod: '伏尔加河在崖下铺开宽得像海，崖顶是红砖城墙和白柱廊的古典楼',
  warsaw: '暗红与赭黄两种砖，老城山墙一层层叠上去，窗是白石膏框',
  krakow: '石板路被磨得发亮，街两侧是暗红砖配米黄灰泥的连排楼，陡坡红瓦，椴树在街心投下整片荫',
  gdansk: '深红与焦褐的砖，山墙一座挨一座，檐口描金，窗是白框小方格',
  wroclaw: '奥得河绕着几座小岛分流，卵石巷两侧是彩色灰泥立面，红瓦压顶，蓝电车从巷口拐过',
  poznan: '浅色石面配一圈文艺复兴连拱廊，屋顶立小尖塔，广场房刷成彩色',
