  torun: '深红与黑褐的砖，市政厅阶梯山墙一层层收上去，窗是窄长白框',
  zakopane: '黑褐原木一层层叠成墙，屋顶陡而长，窗框刷白，后面是灰岩山尖',
  berlin: '五六层公寓楼连成街墙，檐口一圈灰泥花饰，过拱门是碎石内院，椴树沿街排开，墙根留着涂鸦',
  munich: '浅黄灰泥的五层楼围成街块，棕红大坡屋顶压着檐口，石板巷拐进中庭，栗树下摆着长条木桌',
  hamburg: '街两侧五六层的公寓，红砖与灰泥各占一半，山墙顶着屋顶，运河在街尾拐弯，雨一阵一阵地下',
  cologne: '黑褐砂岩的大教堂双塔压在站前，越往上越黑；莱茵河是灰绿，老城山墙刷赭黄和砖红',
  dresden: '易北河贴着城边流过，鹅卵石街窄而弯，砂岩立面熏成灰黑，坡屋顶上立着老虎窗，电车叮当穿巷',
  heidelberg: '白墙红瓦挤在河与山之间的窄带上，石板巷朝坡上爬，学生骑车从巷口铃铛一路响过去',
  nuremberg: '砂岩城墙和方塔立在山头，下面一整片红瓦坡顶，半木房子的木梁深褐',
  vienna: '五六层灰泥立面连成整道街墙，拱窗一排排，门洞里藏着方形内院，电车沿鹅卵石街轧过去',
  salzburg: '巷子宽不过三米，两侧灰泥墙高过二十米，铁艺招牌挑在半空，拱廊穿楼而过，陡屋顶铺到山脚',
  hallstatt: '陡山壁直接插进湖里，水是墨绿；房子挤在窄岸上，屋顶铺深灰木瓦，墙刷白和浅黄',
  zurich: '利马特河把老城劈成两半，水是深青灰；两岸灰泥立面浅灰米白，湖面上反着一片白',
  interlaken: '两片湖夹着一条青绿的河，镇上房子带深褐木阳台；少女峰雪线在云下，针叶林墨绿',
  lucerne: '鹅卵石窄巷弯上去，浅黄淡粉的墙面画满壁画，陡坡屋顶铺红瓦，檐下挂着铁招牌',
  lyon: '石是米白和蜜色，屋顶是低矮的红瓦，索恩河灰绿，山坡上叠着橙红的楼',
  marseille: '石灰岩是灰白，墙刷赭黄和土红，窗装绿木百叶，屋顶浅红瓦，海是蓝绿，夏末山坡草黄',
  nice: '墙是赭黄、橙红和粉，百叶窗刷浅绿，屋顶浅红瓦，海是靛蓝，卵石滩灰白，天光很亮',
  bordeaux: '整条步行街笔直下坡，两侧是蜜色石灰岩立面，深灰板岩屋顶连成一片，电车从中穿过',
  strasbourg: '砂岩是暗粉和砖红，木筋墙刷深棕与土黄，屋顶是灰紫的陡坡瓦，运河水面墨绿',
  avignon: '石是浅黄和蜜色，百叶窗刷褪色的蓝和绿，屋顶浅红瓦，罗讷河灰绿，梧桐树皮斑驳',
  edinburgh: '石是烟灰和蜜黄两种砂岩，屋顶灰板岩，坡地草色暗绿，天压得低，云是铅灰的',
