/**
 * 这个景点有没有自己的锚点。没有就返回空串，调用方退回城市锚点。
 */
export function spotLook(cityId: string | undefined, spot: string | undefined): string {
  if (!cityId || !spot) return '';
  return SPOT_LOOK[cityId]?.[spot] ?? '';
}

