const BY_ID = new Map(CITIES.map((c) => [c.id, c]));

/** 按 id 取。没有就返回 null —— 调用方必须处理"不认识的城"，别拿默认值顶。 */
/**
 * 这个月这座城有哪些演出。
 *
 * 全年排的（字符串）一律算上；带 `months` 的只有当月命中才算。
 * 全部不命中就返回空数组 —— 调用方按「今晚没有剧场」处理，
 * 退回 `night`（夜市、夜游），不要硬塞一场停演的戏。
 */
/**
 * 今晚这座城有什么可去的。**没有就返回 null** —— 调用方回酒店，
 * 不要为了填空硬塞一句别的季节才成立的话。
 */
export function nightIn(city: { readonly night: NightSpot | null }, month: number): string | null {
  const n = city.night;
  if (n === null) return null;
  if (typeof n === 'string') return n;
  return n.months.includes(month) ? n.text : null;
}

/** 不管季节，把这条夜间去处读成一个字符串（面板、测试用）。 */
export function nightText(n: NightSpot | null): string | null {
  if (n === null) return null;
  return typeof n === 'string' ? n : n.text;
}

export function showsIn(city: { readonly shows: readonly Show[] }, month: number): string[] {
  const out: string[] = [];
  for (const s of city.shows) {
    if (typeof s === 'string') out.push(s);
    else if (s.months.includes(month)) out.push(s.name);
  }
  return out;
}

export function cityById(id: string): City | null {
  return BY_ID.get(id.trim().toLowerCase()) ?? null;
}

/** 按名字找。中文名优先，其次英文 id。找不到返回 null。 */
export function cityByName(name: string): City | null {
  const key = name.trim();
  if (!key) return null;
  const lower = key.toLowerCase();
  const byId = BY_ID.get(lower);
  if (byId) return byId;
  for (const c of CITIES) {
    if (c.name === key) return c;
  }
  /*
   * 「北京市」「兰州市」这种带后缀的也认，去掉尾字再试一次。
   *
   * 2026-11-05 补的：**景区类后缀**也要认。同步表里那两行原来写的是
   * 「优胜美地国家公园」「大峡谷国家公园」，代码里叫「优胜美地」「大峡谷」——
   * 表已经改成代码的名字了，但他嘴上说的还是全名。认不出来就是
   * 「内置城市表里没有这个地方」，而那座城明明就在表上。
   *
   * 顺序有讲究：「国家公园」要排在「公园」前面，否则只会被削成「…国家」。
   */
  const stripped = key.replace(
    /(国家公园|森林公园|地质公园|湿地公园|风景区|景区|古城|古镇|地区|特别行政区|市)$/,
    '',
  );
  if (stripped !== key) {
    for (const c of CITIES) {
      if (c.name === stripped) return c;
    }
  }
  return null;
}

/** 国内 / 国外。国外才有时差，也才需要护照这件事出现在叙事里。 */
export function isForeign(c: City): boolean {
  return c.country !== 'CN';
}
